<script setup lang="ts">
import type {Task} from '../shared/types'
defineProps<{form:Task;readonly:boolean}>()
const periods=[{value:1,label:'分钟'},{value:2,label:'小时'},{value:3,label:'天'},{value:4,label:'周'},{value:5,label:'月'},{value:6,label:'季度'},{value:7,label:'年'}]
const weekdays=['星期一','星期二','星期三','星期四','星期五','星期六','星期日'].map((label,i)=>({value:i+1,label}))
</script>
<template><a-divider orientation="left">作业计划</a-divider>
 <a-form-item v-if="form.taskLevel===1" label="任务类型"><a-radio-group v-model:value="form.taskType"><a-radio :value="1">临时任务</a-radio><a-radio :value="2">固定任务</a-radio></a-radio-group></a-form-item>
 <template v-if="form.taskType===2"><a-form-item label="开始时间"><a-date-picker show-time :value="form.startTime" value-format="x" @change="(v:unknown)=>form.startTime=v?Number(v):undefined" /></a-form-item><a-form-item label="结束时间"><a-date-picker show-time :value="form.endTime" value-format="x" @change="(v:unknown)=>form.endTime=v?Number(v):undefined" /></a-form-item></template>
 <template v-if="form.taskLevel===1"><a-form-item label="首次生成时间"><a-date-picker show-time :value="form.firstGenerateTime" value-format="x" @change="(v:unknown)=>form.firstGenerateTime=v?Number(v):undefined" /></a-form-item><a-form-item v-if="form.taskType===2" label="生成间隔"><a-space><a-input-number v-model:value="form.intervalValue" :min="1" :precision="0" /><a-select v-model:value="form.intervalUnit" :options="periods" style="width:110px" /></a-space></a-form-item>
 <a-form-item label="回传时限方式"><a-radio-group :value="form.reportDeadlineValue?'dynamic':'fixed'" @change="(e:{target:{value:string}})=>{if(e.target.value==='dynamic'){form.reportDeadlineValue=1;form.reportDeadlineUnit='DAY'}else{form.reportDeadlineValue=undefined;form.reportDeadlineUnit=undefined}}"><a-radio value="fixed">指定截止时间</a-radio><a-radio value="dynamic">生成后动态计算</a-radio></a-radio-group></a-form-item>
 <a-form-item v-if="form.reportDeadlineValue" label="动态回传时限"><a-space><a-input-number v-model:value="form.reportDeadlineValue" :min="1" :precision="0" /><a-select v-model:value="form.reportDeadlineUnit" :options="[{value:'HOUR',label:'小时'},{value:'DAY',label:'天'}]" style="width:100px" /></a-space></a-form-item><a-form-item v-else label="回传截止时间"><a-date-picker show-time :value="form.reportDeadline" value-format="x" @change="(v:unknown)=>form.reportDeadline=v?Number(v):undefined" /></a-form-item>
 </template>
 <template v-if="form.taskLevel===2&&form.scheduleRules"><a-form-item label="巡检周期"><a-select v-model:value="form.inspectionFrequency" :options="[{value:1,label:'每日'},{value:2,label:'每周'},{value:3,label:'每月'}]" /></a-form-item><a-form-item label="每周期作业次数"><a-input-number v-model:value="form.operationFrequency" :min="1" :precision="0" /></a-form-item>
 <template v-if="form.inspectionFrequency===1"><a-form-item v-for="(_,i) in form.scheduleRules.dayTimes" :key="i" :label="'第'+(i+1)+'次'"><a-space><a-time-picker v-model:value="form.scheduleRules.dayTimes![i]" value-format="HH:mm" format="HH:mm" /><a-button v-if="!readonly" @click="form.scheduleRules.dayTimes!.splice(i,1)">移除</a-button></a-space></a-form-item><a-button v-if="!readonly" @click="form.scheduleRules.dayTimes!.push('09:00')">添加日作业时间</a-button></template>
 <template v-if="form.inspectionFrequency===2"><a-form-item v-for="(point,i) in form.scheduleRules.weekTimes" :key="i" :label="'第'+(i+1)+'次'"><a-space><a-select v-model:value="point.weekDay" :options="weekdays" style="width:120px" /><a-time-picker v-model:value="point.time" value-format="HH:mm" format="HH:mm" /><a-button v-if="!readonly" @click="form.scheduleRules.weekTimes!.splice(i,1)">移除</a-button></a-space></a-form-item><a-button v-if="!readonly" @click="form.scheduleRules.weekTimes!.push({weekDay:1,time:'09:00'})">添加周作业时间</a-button></template>
 <template v-if="form.inspectionFrequency===3"><a-form-item v-for="(_,i) in form.scheduleRules.monthDateTimes" :key="i" :label="'作业日期'+(i+1)"><a-space><a-date-picker v-model:value="form.scheduleRules.monthDateTimes![i]" show-time format="YYYY-MM-DD HH:mm" value-format="YYYY-MM-DD HH:mm" /><a-button v-if="!readonly" @click="form.scheduleRules.monthDateTimes!.splice(i,1)">移除</a-button></a-space></a-form-item><a-button v-if="!readonly" @click="form.scheduleRules.monthDateTimes!.push('')">添加月作业日期</a-button></template>
 </template></template>
